INSERT INTO feature VALUES('cylinder-composites','identity','Cylinder and cone composites of paths','math-path','partial','notable',NULL,'`std.math.cylinder` composes squares of paths side by side, `cylinderComposite2`, and stacked, `cylinderStack2`, and triangles of paths over one apex, `coneComposite2`, at dimension 2: each is the term Catt''s built-in `cylcomp`, `cylstack` or `conecomp` prints, written over the associator and the whiskers of `std.math.path`, and the kernel replays each. The cells reading, `cylinderCompositeCells2`, `cylinderStackCells2` and `coneCompositeCells2`, writes each as its whiskers, level-two composites joined by `Path.step`, its sides one composite over the 3-chain and no associator written. The composite at `n + 1` is `fill` at the composite at `n`: `cylinderFill2` is Example 1.2, `fill` at the 2-chain''s whole context, and `cylinderFill3` is the level-two `fill` over `[2](1, 1)` at `cylinderFill2` with its points fixed, curried as `cylinderFillOver2`. The corpus states the type Catt answers for `cylcomp(3,1,3)` at identity verticals, its whiskers by identities and its square as Catt prints them, and inhabits it by `cylinderFill3` through 3-paths that based path induction proves. Along dimension 2 the step suspends: `cylinderSuspended3` is `cylinderFill2` at a path type between the interchangers `interchangeRight` and `interchangeLeft`, which based path induction proves, and `coneSuspended3` is `coneOpposite2`, the opposite cone composite, at a path type after `interchangeRight`. Each states the type Catt prints for `cylcomp(3,2,3)` or `conecomp(3,2,3)`. The kernel replays each, and `bench:stress` sets each beside Catt''s built-in. The composites along dimension 1 at dimension 3 with their verticals free are owed.',NULL,'library/std/src/math/cylinder.gandr','corpus/ledger/features/cylinder-composites.gandr','#4240');
